def values(self, *keys):
    """
    Return the values of the record, optionally filtering to
    include only certain values by index or key.

    :param keys: indexes or keys of the items to include; if none
                 are provided, all values will be included
    :return: list of values
    :rtype: list
    """
    # Try to obtain the items of the record in order
    try:
        items = list(self.items())
    except AttributeError:
        # Fallback: look for a common internal attribute
        if hasattr(self, "_data"):
            items = list(self._data.items())
        else:
            raise AttributeError("Record object has no items() method or _data attribute")

    if not keys:
        # Return all values
        return [v for _, v in items]

    result = []
    for key in keys:
        if isinstance(key, int):
            # Treat as positional index
            try:
                result.append(items[key][1])
            except IndexError:
                raise IndexError(f"Index {key} out of range")
        else:
            # Treat as key lookup
            for k, v in items:
                if k == key:
                    result.append(v)
                    break
            else:
                raise KeyError(f"Key {key} not found")
    return result

