def validate_hierarchy(self, validate_objects=True, check_digests=True, show_warnings=False):
    """
    Validate storage root hierarchy.

    Returns:
        num_objects - number of objects checked
        good_objects - number of objects checked that were found to be valid
    """
    # Retrieve the collection of objects; fall back to empty list if not present
    objects = getattr(self, 'objects', [])
    num_objects = 0
    good_objects = 0

    for obj in objects:
        num_objects += 1
        is_valid = True

        # Validate the object if requested
        if validate_objects:
            if hasattr(obj, 'validate'):
                try:
                    is_valid = bool(obj.validate())
                except Exception as exc:
                    is_valid = False
                    if show_warnings:
                        print(f"Warning: validation failed for {obj!r} with error: {exc}")
            else:
                # If no validate method, assume valid
                is_valid = True

        # Check the digest if requested and the object is still considered valid
        if check_digests and is_valid:
            if hasattr(obj, 'check_digest'):
                try:
                    digest_ok = bool(obj.check_digest())
                except Exception as exc:
                    digest_ok = False
                    if show_warnings:
                        print(f"Warning: digest check failed for {obj!r} with error: {exc}")
                if not digest_ok:
                    is_valid = False
            else:
                # If no check_digest method, assume digest is okay
                digest_ok = True

        if is_valid:
            good_objects += 1

    return num_objects, good_objects

def next_version(version):
    """Next version identifier following existing pattern.

    Must deal with both zero-prefixed and non-zero prefixed versions.
    """
    if not version:
        return version
    parts = version.split('.')
    # Find the last numeric part to increment
    for i in range(len(parts) - 1, -1, -1):
        part = parts[i]
        if part.isdigit():
